#include <cstdio>
#include <algorithm>
using namespace std;

int nod(int m, int n) {
    if (n == 0) return m;
    return nod(n, m % n);
}

int main() {
    freopen("input.txt", "r", stdin);
    freopen("output.txt", "w", stdout);

    int a, b;
    cin >> a >> b;

    int k = nod(max(a, b), min(a, b));
    cout << min(a, b) / k << '/' << max(a, b) / k;

    return 0;
}

